CREATE TABLE verification_revision_scan(plan_id TINYINT PRIMARY KEY,completed_event_id BIGINT NOT NULL DEFAULT 0,event_id BIGINT NULL,instrument_id VARCHAR(64) NULL,raw_version_id CHAR(36) NULL,cutoff_date DATE NULL,after_id CHAR(36) NULL,revision BIGINT NOT NULL DEFAULT 0,updated_at DATETIME(3) NOT NULL,CHECK(plan_id=1),CHECK(completed_event_id>=0),CHECK((event_id IS NULL AND instrument_id IS NULL AND raw_version_id IS NULL AND cutoff_date IS NULL AND after_id IS NULL) OR (event_id>completed_event_id AND instrument_id IS NOT NULL AND raw_version_id IS NOT NULL AND cutoff_date IS NOT NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
